"""Apply and run RABIT-2 Stage 3B2 single-sequence online integration.

Run from the kvquant_pkg project root with the same Python/Modal environment used
for Stage 3B1.

Stage 3B2 adds:
- bounded exact open-K / V2-primary / R4 sidecar state;
- direct writes of closed 32-token pages into the opaque vLLM KV cache;
- Triton raw-page packed K3/V2 + META8g64 decode attention over all closed pages;
- exact tail participation in the same global softmax;
- backend dispatch for one active decoder sequence;
- unchunked initial prefill + one-token decode;
- an actual TinyLlama vLLM engine smoke on H100.

Still intentionally unsupported at this stage: multi-sequence batching, chunked
prefill, prefix caching, sliding/chunked attention, ALiBi/sinks/softcap.
"""
from __future__ import annotations

import base64
import os
import shutil
import subprocess
import sys
import tempfile
import time
import zipfile
import zlib
from pathlib import Path

PROJECT_ROOT = Path.cwd().resolve()
VLLM_ROOT = PROJECT_ROOT / "vllm-kvquant"
RABIT_PATH = VLLM_ROOT / "vllm/v1/attention/ops/rabit_kv2.py"
TRITON_ATTN_PATH = VLLM_ROOT / "vllm/v1/attention/backends/triton_attn.py"
RESHAPE_PATH = VLLM_ROOT / "vllm/v1/attention/ops/triton_reshape_and_cache_flash.py"
UNIFIED_PATH = VLLM_ROOT / "vllm/v1/attention/ops/triton_unified_attention.py"
TEST_PATH = VLLM_ROOT / "tests/quantization/test_rabit_kv2_stage3b2.py"
BACKUP_ROOT = PROJECT_ROOT / "rabit2_stage3b2_backup"
SNAPSHOT_PATH = Path(tempfile.gettempdir()) / "rabit2_stage3b2_vllm_snapshot.zip"
RUNNER_PATH = Path(tempfile.gettempdir()) / "modal_rabit2_stage3b2_frozen_test.py"
LOG_PATH = PROJECT_ROOT / "rabit2_stage3b2.log"

BEGIN = "# === RABIT2_STAGE3B2_SINGLESEQ_BEGIN ==="
END = "# === RABIT2_STAGE3B2_SINGLESEQ_END ==="

FRAGMENT_Z = ''
TEST_Z = ''
ATTN_Z = ''
RESHAPE_Z = ''
UNIFIED_Z = ''
RUNNER_Z = ''

IGNORED_DIR_NAMES = {
    ".git", ".github", ".buildkite", ".venv", "__pycache__", "build",
    "dist", "docs", "examples", "benchmarks", ".deps", ".pytest_cache",
    ".mypy_cache", ".ruff_cache",
}
IGNORED_SUFFIXES = {".pyc", ".pyo", ".so", ".dll", ".dylib"}


def _decode(value: str) -> str:
    return zlib.decompress(base64.b64decode(value.encode("ascii"))).decode("utf-8")


def _backup(path: Path) -> None:
    if not path.exists():
        return
    rel = path.relative_to(PROJECT_ROOT)
    dst = BACKUP_ROOT / rel
    if not dst.exists():
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, dst)


def _strip_stage3b2(text: str) -> str:
    if BEGIN not in text:
        return text.rstrip() + "\n"
    before, rest = text.split(BEGIN, 1)
    if END not in rest:
        raise RuntimeError("Found Stage3B2 begin marker without end marker")
    _, after = rest.split(END, 1)
    return (before.rstrip() + "\n" + after.lstrip()).rstrip() + "\n"


def _install() -> None:
    required_paths = [RABIT_PATH, TRITON_ATTN_PATH, RESHAPE_PATH, UNIFIED_PATH]
    missing_paths = [str(p) for p in required_paths if not p.is_file()]
    if missing_paths:
        raise FileNotFoundError(f"Missing required vLLM sources: {missing_paths}")

    rabit = RABIT_PATH.read_text(encoding="utf-8")
    required = [
        "RABIT2_STAGE3B1_TRITON_BEGIN",
        "encode_rabit2_page_exact_cuda",
        "decode_rabit2_page_triton",
        "rabit2_closed_page_attention_triton",
        "Rabit2OnlineStateRef",
    ]
    missing = [x for x in required if x not in rabit]
    if missing:
        raise RuntimeError(
            "Stage3B2 requires the passed Stage3B1 source first; missing " + repr(missing)
        )

    for path in required_paths + [TEST_PATH]:
        _backup(path)

    rabit = _strip_stage3b2(rabit)
    rabit = rabit.rstrip() + "\n" + _decode(FRAGMENT_Z).lstrip()
    compile(rabit, str(RABIT_PATH), "exec")
    RABIT_PATH.write_text(rabit, encoding="utf-8")

    replacements = [
        (TRITON_ATTN_PATH, ATTN_Z),
        (RESHAPE_PATH, RESHAPE_Z),
        (UNIFIED_PATH, UNIFIED_Z),
        (TEST_PATH, TEST_Z),
    ]
    for path, payload in replacements:
        text = _decode(payload)
        compile(text, str(path), "exec")
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")

    print(f"Installed Stage3B2 runtime:  {RABIT_PATH}")
    print(f"Installed backend dispatch: {TRITON_ATTN_PATH}")
    print(f"Installed cache guard:      {RESHAPE_PATH}")
    print(f"Installed unified guard:    {UNIFIED_PATH}")
    print(f"Installed Stage3B2 tests:   {TEST_PATH}")


def _preflight() -> None:
    checks = {
        RABIT_PATH: [
            BEGIN,
            "class Rabit2SingleSequenceRuntime",
            "rabit2_online_decode_attention_triton",
            "_rabit2_closed_page_partial_kernel",
        ],
        TRITON_ATTN_PATH: [
            "def _forward_rabit_kv2",
            "Rabit2SingleSequenceRuntime",
            "RABIT_KV2 cache update is deferred",
        ],
        RESHAPE_PATH: ["RABIT_KV2 cache update is deferred"],
        UNIFIED_PATH: ["RABIT_KV2 uses the backend sidecar dispatch"],
    }
    for path, needles in checks.items():
        text = path.read_text(encoding="utf-8")
        miss = [x for x in needles if x not in text]
        if miss:
            raise RuntimeError(f"Stage3B2 preflight {path.name} missing {miss}")
        compile(text, str(path), "exec")
    print("Stage 3B2 local source preflight: PASSED")


def _include(path: Path) -> bool:
    rel = path.relative_to(VLLM_ROOT)
    return (
        path.is_file()
        and not any(part in IGNORED_DIR_NAMES for part in rel.parts)
        and path.suffix.lower() not in IGNORED_SUFFIXES
        and not path.name.endswith(".egg-info")
    )


def _make_snapshot() -> None:
    tmp = SNAPSHOT_PATH.with_suffix(".zip.tmp")
    for path in (tmp, SNAPSHOT_PATH):
        try:
            path.unlink()
        except FileNotFoundError:
            pass
    count = 0
    with zipfile.ZipFile(tmp, "w", zipfile.ZIP_DEFLATED, compresslevel=6) as zf:
        for path in sorted(VLLM_ROOT.rglob("*")):
            if _include(path):
                zf.write(path, path.relative_to(VLLM_ROOT).as_posix())
                count += 1
    os.replace(tmp, SNAPSHOT_PATH)
    print(
        f"Created frozen vLLM snapshot: {SNAPSHOT_PATH} "
        f"({count} files, {SNAPSHOT_PATH.stat().st_size / 1024**2:.1f} MB)"
    )


def _run_modal() -> int:
    RUNNER_PATH.write_text(_decode(RUNNER_Z), encoding="utf-8")
    time.sleep(2)
    env = os.environ.copy()
    env.setdefault("PYTHONUTF8", "1")
    env.setdefault("PYTHONIOENCODING", "utf-8")
    command = [sys.executable, "-m", "modal", "run", str(RUNNER_PATH)]
    print("Running:", " ".join(command))
    with LOG_PATH.open("w", encoding="utf-8") as log:
        process = subprocess.Popen(
            command,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            encoding="utf-8",
            errors="replace",
            env=env,
            bufsize=1,
        )
        assert process.stdout is not None
        for line in process.stdout:
            print(line, end="")
            log.write(line)
            log.flush()
        return process.wait()


def main() -> None:
    print("RABIT-2 Stage 3B2 installer + H100 lifecycle/engine runner")
    print(f"Project root: {PROJECT_ROOT}")
    _install()
    _preflight()
    _make_snapshot()
    code = _run_modal()
    if code != 0:
        raise SystemExit(code)
    print(f"Log saved to: {LOG_PATH}")


if __name__ == "__main__":
    main()
